290	     * For tests that are applied to a single source file (or are rooted at a
291	     * single source file), this takes care of checking for success/failure,
292	     * what is expected, printing, etc.
293	     */
294	    public abstract static class SourceFileTest extends BaseTest {
295	        public SourceFileTest(String path,
296	                              String d,
297	                              String s,
298	                              boolean unexpected_only,
299	                              boolean knownFailure,
300	                              boolean shouldFail) {
301	            super(path, d, s, unexpected_only, knownFailure, shouldFail);
302	        }
303	
304	        public abstract String tag();
305	
306	        public void testFile() throws Throwable {
307	            // Useful when a test is running forever
308	            //            System.out.println(this.name);
309	            //            System.out.flush();
310	
311	            PrintStream oldOut = System.out;
312	            PrintStream oldErr = System.err;
313	            WireTappedPrintStream wt_err = WireTappedPrintStream.make(System.err, unexpectedOnly);
314	            WireTappedPrintStream wt_out = WireTappedPrintStream.make(System.out, unexpectedOnly);
315	            System.setErr(wt_err);
316	            System.setOut(wt_out);
317	
318	
319	            long start = System.nanoTime();
320	            //String fssFile = f + ".fss";
321	            int rc = 0;
322	            StringMap refusal = loadRefusalKeys();
323	
324	            try {
325	                //BufferedReader in = null;
326	                try {
327	                    oldOut.print(" " + tag() + " ");
328	                    oldOut.print(f);
329	                    oldOut.print(" ");
330	                    oldOut.flush();
331	                    //in = Useful.utf8BufferedFileReader(fssFile);
332	
333	                    rc = justTheTest();
334	                }
335	                finally {
336	                    System.setErr(oldErr);
337	                    System.setOut(oldOut);
338	                    //if (in != null)
339	                    //    in.close();
340	                }
341	            }
342	            catch (Throwable ex) {
343	                String outs = wt_out.getString();
344	                String errs = wt_err.getString();
345	                if (refusal != null) {
346	                    refusalVerdict(refusal, wt_err, wt_out, outs, errs, ex, true);
347	                    return;
348	                }
349	                String exFirstLine = ex.toString();
350	                String trueFailure = testFailed(outs, errs, exFirstLine);
351	                if (f.contains("XXX")) {
352	                    if (trueFailure != null) {
353	                        unexpectedExceptionBoilerplate(wt_err, wt_out, ex, " Did not satisfy " + trueFailure);
354	                        return;
355	
356	                    } else {
357	                        // "Failed", but correctly
358	                        // !unexpectedOnly || expectFailure
359	                        wt_err.flush(printSuccess);
360	                        wt_out.flush(printSuccess);
361	                        int crLoc = exFirstLine.indexOf("\n");
362	                        if (crLoc == -1) crLoc = exFirstLine.length();
363	                        exFirstLine = exFirstLine.substring(0, crLoc);
364	                        if (printSuccess) System.out.println(exFirstLine);
365	                        System.out.println(" OK Saw expected exception");
366	                        return;
367	                    }
368	                } else {
369	                    unexpectedExceptionBoilerplate(wt_err, wt_out, ex, " UNEXPECTED exception ");
370	                    // return;
371	                }
372	            }
373	            finally {
374	                //fr.clear();
375	            }
376	
377	            /* Come here IFF NO EXCEPTIONS, to analyze output */
378	
379	            String outs = wt_out.getString();
380	            String errs = wt_err.getString();
381	
382	            boolean anyFails = ! f.contains("QuickCheckTest") &&
383	                               (outs.contains("fail") || outs.contains("FAIL") ||
384	                                errs.contains("fail") || errs.contains("FAIL") ||
385	                                rc != 0);
386	
387	            if (refusal != null) {
388	                refusalVerdict(refusal, wt_err, wt_out, outs, errs, null, anyFails);
389	                return;
390	            }
391	
392	            String trueFailure = testFailed(outs, errs, "");
393	
394	            if (shouldFail) {
395	                // NOTE expect to see this on STANDARD OUTPUT, not ERROR.
396	                if (anyFails && trueFailure == null) {
397	                    wt_err.flush(printSuccess);
398	                    wt_out.flush(printSuccess);
399	                    // Saw a failure, that is good.
400	                    System.out.println(" Saw expected failure");
401	                } else {
402	                    if (printFailure) System.out.println();
403	                    wt_err.flush(printFailure);
404	                    wt_out.flush(printFailure);
405	                    if (trueFailure != null) {
406	                        System.out.println(" Saw failure, but did not satisfy " + trueFailure);
407	                        // Expected exception, saw none.
408	                        fail("Saw wrong failure. " + whoami());
409	                    } else {
410	                        System.out.println(" Missing expected failure ");
411	                        // Expected exception, saw none.
412	                        fail("Expected failure or exception, saw none. " + whoami());
413	                    }
414	                }
415	            } else {
416	                // This logic is a little confusing.
417	                // Failure is failure.  TrueFailure contains the better message.
418	                if (anyFails && trueFailure == null) trueFailure = "FAIL or fail should not appear in output";
419	
420	                long duration = (System.nanoTime() - start) / 1000000;
421	                System.out.println(trueFailure != null ? " FAIL" : " OK (time = " + duration + "ms)");
422	                wt_err.flush(trueFailure != null ? printFailure : printSuccess);
423	                wt_out.flush(trueFailure != null ? printFailure : printSuccess);
424	
425	                assertTrue("Must satisfy " + trueFailure + " " + whoami(), trueFailure == null);
426	
427	            }
428	        }
429	
430	        /**
431	         * @param wt_err
432	         * @param wt_out
433	         * @param ex
434	         * @param s
435	         * @throws IOException
436	         */
437	        private void unexpectedExceptionBoilerplate(WireTappedPrintStream wt_err,
438	                                                    WireTappedPrintStream wt_out,
439	                                                    Throwable ex,
440	                                                    String s) throws IOException {
441	            if (printFailure) System.out.println();
442	            wt_err.flush(printFailure);
443	            wt_out.flush(printFailure);
444	            if (printFailure) {
445	                System.out.println(s);
446	                ex.printStackTrace();
447	                fail(whoami());
448	            } else {
449	                System.out.println(s);
450	                fail(ex.getMessage() + " " + whoami());
451	            }
452	        }
453	
454	        abstract protected int justTheTest() throws FileNotFoundException, IOException, Throwable;
455	
456	        /**
457	         * The keys by which this test names a refusal at load that it
458	         * expects, or null when it names none.
459	         */
460	        protected StringMap loadRefusalKeys() {
461	            return null;
462	        }
463	
464	        /**
465	         * Whether ex was thrown while the program was loaded, before it ran.
466	         */
467	        protected boolean thrownAtLoad(Throwable ex) {
468	            return false;
469	        }
470	
471	        /**
