576	        private Long handle(GraphNode node) throws FileNotFoundException {
577	            if (youngestSourceDependedOn.containsKey(node)) {
578	                return youngestSourceDependedOn.get(node);
579	            }
580	            long youngest = node.getSourceDate();
581	            youngestSourceDependedOn.put(node, youngest);
582	
583	            List<GraphNode> depends = graph.depends(node);
584	            Debug.debug(Debug.Type.REPOSITORY, 2, node, " depends on ", depends);
585	            for (GraphNode next : depends) {
586	                if (foreignJava.definesApi(next)) {
587	                    // no date information here; need to look for the dependence
588	                    // info for this node.
589	                    if (foreignJava.dependenceChanged(node, next)) {
590	                        Debug.debug(Debug.Type.REPOSITORY, 1, "" + node + " added to foreign change by change in " + next);
591	                        foreignChange.add(node);
592	                    }
593	                }
594	
595	                long dependent_youngest = handle(next);
596	                if (dependent_youngest > youngest) {
597	
598	                    Debug.debug(Debug.Type.REPOSITORY, 3, next + " has younger source than " + node);
599	                    youngest = dependent_youngest;
600	                }
601	
602	            }
603	
604	            youngestSourceDependedOn.put(node, youngest);
605	
606	            return youngest;
607	        }
608	
609	        private Boolean isStale(GraphNode node) throws FileNotFoundException {
610	            if (staleOrDependsOnStale.containsKey(node)) {
611	                return staleOrDependsOnStale.get(node);
612	            }
613	
614	            boolean stale1 = youngestSourceDependedOn.get(node) > getCacheDate(node);
615	            boolean stale2 = foreignChange.contains(node);
616	            boolean stale = stale1 || stale2;
617	            
618	            // If anything depended on has source that is younger than our compiled code,
619	            // then this is stale.
620	            if (stale) {
621	                if (stale1)
622	                    Debug.debug(Debug.Type.REPOSITORY,
623	                            1,
624	                            node,
625	                            " or dependent is newer ",
626	                            youngestSourceDependedOn.get(node),
627	                            " than the cache ",
628	                            getCacheDate(node));
629	                if (stale2)
630	                    Debug.debug(Debug.Type.REPOSITORY,
631	                            1,
632	                            node, " is in foreign change ", foreignChange);
633	                    
634	            }
635	
636	            staleOrDependsOnStale.put(node, stale);
637	
638	            List<GraphNode> depends = graph.depends(node);
639	            Debug.debug(Debug.Type.REPOSITORY, 2, node, " depends on ", depends);
640	            for (GraphNode next : depends) {
641	                boolean dependent_stale = isStale(next);
642	
643	                if (dependent_stale) {
644	                    stale = true;
645	                    Debug.debug(Debug.Type.REPOSITORY, 1, node, " is stale ", next, " is stale");
646	                    staleOrDependsOnStale.put(node, stale);
647	                }
648	            }
649	            return stale;
650	        }
651	
652	        public Boolean visit(ApiGraphNode node) throws FileNotFoundException {
653	            handle(node);
